                    let mask: u32 = (_mm256_movemask_epi8(_mm256_cmpeq_epi8(_mm256_loadu_si256(end.sub(32usize) as *const __m256i), v1)) as u32);
                    let shift: u32 = ((32usize - rem) as u32);
                    count = (count + ((mask >> shift).count_ones() as usize));
