    /// byte-at-a-time fallback
    #[inline(always)]
    pub(crate) unsafe fn nvol_first_non_ascii_scalar(start: *const u8, end: *const u8) -> *const u8 {
        unsafe {
            let mut p: *const u8 = start;
            while (p < end) {
                if ((*p) >= 128u8) {
                    return p;
                }
                p = p.add(1usize);
            }
            return core::ptr::null();
        }
    }

    /// requires len >= 16
    #[inline(always)]
    pub(crate) unsafe fn nvol_first_non_ascii_sse2(start: *const u8, end: *const u8) -> *const u8 {
        unsafe {
            let len_: usize = ((end as usize) - (start as usize));
            let mask: u32 = (_mm_movemask_epi8(_mm_loadu_si128(start as *const __m128i)) as u32);
            if (mask != 0u32) {
                return start.add((mask.trailing_zeros() as usize));
            }
            let mut cur: *const u8 = start.add((16usize - ((start as usize) & 15usize)));
            if (len_ >= 64usize) {
                while (cur <= end.sub(64usize)) {
                    let ld: __m128i = _mm_load_si128(cur as *const __m128i);
                    let ld1: __m128i = _mm_load_si128(cur.add(16usize) as *const __m128i);
                    let ld2: __m128i = _mm_load_si128(cur.add(32usize) as *const __m128i);
                    let ld3: __m128i = _mm_load_si128(cur.add(48usize) as *const __m128i);
                    if ((_mm_movemask_epi8(_mm_or_si128(_mm_or_si128(ld, ld1), _mm_or_si128(ld2, ld3))) as u32) != 0u32) {
                        let mask1: u32 = (_mm_movemask_epi8(ld) as u32);
                        if (mask1 != 0u32) {
                            return cur.add((mask1.trailing_zeros() as usize));
                        }
                        let mask2: u32 = (_mm_movemask_epi8(ld1) as u32);
                        if (mask2 != 0u32) {
                            return cur.add(16usize).add((mask2.trailing_zeros() as usize));
                        }
                        let mask3: u32 = (_mm_movemask_epi8(ld2) as u32);
                        if (mask3 != 0u32) {
                            return cur.add(32usize).add((mask3.trailing_zeros() as usize));
                        }
                        let mask4: u32 = (_mm_movemask_epi8(ld3) as u32);
                        if (mask4 != 0u32) {
                            return cur.add(48usize).add((mask4.trailing_zeros() as usize));
                        }
                    }
                    cur = cur.add(64usize);
                }
            }
            while (cur <= end.sub(16usize)) {
                let mask5: u32 = (_mm_movemask_epi8(_mm_loadu_si128(cur as *const __m128i)) as u32);
                if (mask5 != 0u32) {
                    return cur.add((mask5.trailing_zeros() as usize));
                }
                cur = cur.add(16usize);
            }
            if (cur < end) {
                cur = end.sub(16usize);
                let mask6: u32 = (_mm_movemask_epi8(_mm_loadu_si128(cur as *const __m128i)) as u32);
                if (mask6 != 0u32) {
                    return cur.add((mask6.trailing_zeros() as usize));
                }
            }
            return core::ptr::null();
        }
    }

