    /// x[0..n) == y[0..n)
    #[inline(always)]
    pub(crate) unsafe fn nvol_is_equal(x: *const u8, y: *const u8, n: usize) -> bool {
        unsafe {
            let mut k: usize = 0usize;
            while ((k + 4usize) <= n) {
                if ((x.add(k) as *const u32).read_unaligned() != (y.add(k) as *const u32).read_unaligned()) {
                    return false;
                }
                k = (k + 4usize);
            }
            if ((k + 2usize) <= n) {
                if (((x.add(k) as *const u16).read_unaligned() as u32) != ((y.add(k) as *const u16).read_unaligned() as u32)) {
                    return false;
                }
                k = (k + 2usize);
            }
            if (k < n) {
                if ((*x.add(k)) != (*y.add(k))) {
                    return false;
                }
            }
            return true;
        }
    }

    /// Rabin-Karp; any lengths
    #[inline(always)]
    pub(crate) unsafe fn nvol_memmem_rk(state: *const u8, nstart: *const u8, nend: *const u8, hstart: *const u8, hend: *const u8) -> *const u8 {
        unsafe {
            let nlen: usize = ((nend as usize) - (nstart as usize));
            let hlen: usize = ((hend as usize) - (hstart as usize));
            if (nlen > hlen) {
                return core::ptr::null();
            }
            let nhash: u32 = ((state.add(16usize) as *const u64).read_unaligned() as u32);
            let pow2: u32 = ((state.add(24usize) as *const u64).read_unaligned() as u32);
            let last: *const u8 = hend.sub(nlen);
            let mut hash: u32 = 0u32;
            let mut p: *const u8 = hstart;
            while (p < hstart.add(nlen)) {
                hash = (hash << 1u32).wrapping_add(((*p) as u32));
                p = p.add(1usize);
            }
            let mut cur: *const u8 = hstart;
            while true {
                if ((hash == nhash) && nvol_is_equal(cur, nstart, nlen)) {
                    return cur;
                }
                if (cur >= last) {
                    return core::ptr::null();
                }
                hash = (hash.wrapping_sub(((*cur) as u32).wrapping_mul(pow2)) << 1u32).wrapping_add(((*cur.add(nlen)) as u32));
                cur = cur.add(1usize);
            }
            return core::ptr::null();
        }
    }

    /// Rabin-Karp without a Finder: first needle [nstart, nend) in [hstart, hend), or NULL
    #[inline(always)]
    pub unsafe fn nvol_memmem_rk_oneshot(nstart: *const u8, nend: *const u8, hstart: *const u8, hend: *const u8) -> *const u8 {
        unsafe {
            let nlen: usize = ((nend as usize) - (nstart as usize));
            let hlen: usize = ((hend as usize) - (hstart as usize));
            if (nlen > hlen) {
                return core::ptr::null();
            }
            let mut nh: u32 = 0u32;
            let mut pw: u32 = 1u32;
            let mut np: *const u8 = nstart;
            while (np < nend) {
                nh = (nh << 1u32).wrapping_add(((*np) as u32));
                if (np > nstart) {
                    pw = (pw << 1u32);
                }
                np = np.add(1usize);
            }
            let last: *const u8 = hend.sub(nlen);
            let mut hash: u32 = 0u32;
            let mut p: *const u8 = hstart;
            while (p < hstart.add(nlen)) {
                hash = (hash << 1u32).wrapping_add(((*p) as u32));
                p = p.add(1usize);
            }
            let mut cur: *const u8 = hstart;
            while true {
                if ((hash == nh) && nvol_is_equal(cur, nstart, nlen)) {
                    return cur;
                }
                if (cur >= last) {
                    return core::ptr::null();
                }
                hash = (hash.wrapping_sub(((*cur) as u32).wrapping_mul(pw)) << 1u32).wrapping_add(((*cur.add(nlen)) as u32));
                cur = cur.add(1usize);
            }
            return core::ptr::null();
        }
    }

    /// Two-Way critical factorization helper (needle < 4 GiB)
