    /// Copy [start, end) to dst up to the first byte in the class built by nvol_byteset_init; returns that byte's address, or end. dst needs room for end - start bytes (whole vectors are stored, so bytes after the copied prefix may change); no overlap.
    #[inline(always)]
    pub unsafe fn nvol_copy_until_byteset_raw(cls: *const u8, start: *const u8, end: *const u8, dst: *mut u8) -> *const u8 {
        use core::sync::atomic::{AtomicPtr, Ordering};
        type F = unsafe fn(*const u8, *const u8, *const u8, *mut u8) -> *const u8;
        static FN: AtomicPtr<()> = AtomicPtr::new(resolve as F as *mut ());
        unsafe fn resolve(cls: *const u8, start: *const u8, end: *const u8, dst: *mut u8) -> *const u8 {
            let mut f: F = nvol_copy_until_byteset_entry_base;
            if std::is_x86_feature_detected!("avx2") { f = nvol_copy_until_byteset_entry_avx2; }
            FN.store(f as *mut (), Ordering::Relaxed);
            unsafe { f(cls, start, end, dst) }
        }
        let f = FN.load(Ordering::Relaxed);
        unsafe { core::mem::transmute::<*mut (), F>(f)(cls, start, end, dst) }
    }

    /// Every chunk with pair candidates, in order, to visit->fn(ctx, chunk, mask) (mask as in nvol_find_byteset_pair_mask_raw); returns the chunk where the visitor returned true, or NULL at the end. Inline the _visit kernels to fuse the visitor into their loop.
