                prev = ones;
                prev1 = ones;
                let chunk1: uint8x16_t = vld1q_u8(cur);
                let hlo1: uint8x16_t = vandq_u8(chunk1, lomask);
                let hhi1: uint8x16_t = vshrq_n_u8::<4>(chunk1);
                let res3: uint8x16_t = vandq_u8(vqtbl1q_u8(lo, hlo1), vqtbl1q_u8(hi, hhi1));
                let res4: uint8x16_t = vandq_u8(vqtbl1q_u8(lo1, hlo1), vqtbl1q_u8(hi1, hhi1));
                let res5: uint8x16_t = vandq_u8(vqtbl1q_u8(lo2, hlo1), vqtbl1q_u8(hi2, hhi1));
                let cand1: uint8x16_t = vandq_u8(vextq_u8::<15>(prev1, res4), vandq_u8(vextq_u8::<14>(prev, res3), res5));
                prev = res3;
                prev1 = res4;
