#[inline]
pub fn first_non_ascii(hay: &[u8]) -> Option<usize> {
    let s = hay.as_ptr();
    #[cfg(target_arch = "x86_64")]
    if hay.len() >= 16 && hay.len() < 32 {
        use core::arch::x86_64::{__m128i, _mm_loadu_si128, _mm_movemask_epi8};
        let t = hay.len() - 16;
        let (a, b) = unsafe { (_mm_movemask_epi8(_mm_loadu_si128(s as *const __m128i)) as u32,
                               _mm_movemask_epi8(_mm_loadu_si128(s.add(t) as *const __m128i)) as u32) };
        return if a != 0 { Some(a.trailing_zeros() as usize) }
               else if b != 0 { Some(t + b.trailing_zeros() as usize) } else { None };
    }
    let p = unsafe { raw::nvol_first_non_ascii_raw(s, s.add(hay.len())) };
    if p.is_null() { None } else { Some(p as usize - s as usize) }
}

/// Iterator over match positions (memchr::Memchr equivalent). Double-ended.
#[derive(Clone, Debug)]
pub struct Memchr<'h> { n1: u8, base: *const u8, lo: *const u8, hi: *const u8, _h: core::marker::PhantomData<&'h [u8]> }
impl<'h> Memchr<'h> {
    #[inline]
    pub fn new(n1: u8, hay: &'h [u8]) -> Self {
        let p = hay.as_ptr();
        Self { n1, base: p, lo: p, hi: unsafe { p.add(hay.len()) }, _h: core::marker::PhantomData }
    }
}
impl<'h> Iterator for Memchr<'h> {
    type Item = usize;
    #[inline]
    fn next(&mut self) -> Option<usize> {
        unsafe {
            let at = raw::nvol_memchr_raw(self.n1, self.lo, self.hi);
            if at.is_null() { self.lo = self.hi; return None; }
            self.lo = at.add(1);
            Some(at as usize - self.base as usize)
        }
    }
    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) { (0, Some(self.hi as usize - self.lo as usize)) }
    #[inline]
    fn count(self) -> usize { unsafe { raw::nvol_count_raw(self.n1, self.lo, self.hi) } }
}
impl<'h> DoubleEndedIterator for Memchr<'h> {
    #[inline]
    fn next_back(&mut self) -> Option<usize> {
        unsafe {
            let at = raw::nvol_memrchr_raw(self.n1, self.lo, self.hi);
            if at.is_null() { self.hi = self.lo; return None; }
            self.hi = at;
            Some(at as usize - self.base as usize)
        }
    }
}
impl<'h> core::iter::FusedIterator for Memchr<'h> {}
#[inline] pub fn memchr_iter<'h>(n1: u8, hay: &'h [u8]) -> Memchr<'h> { Memchr::new(n1, hay) }
#[inline] pub fn memrchr_iter<'h>(n1: u8, hay: &'h [u8]) -> core::iter::Rev<Memchr<'h>> { Memchr::new(n1, hay).rev() }

