/// Substring search (memchr::memmem equivalent).
pub mod memmem {
    use super::raw;
    pub const STATE_WORDS: usize = 8;

    /// Build once per needle, search many haystacks (memchr::memmem::Finder).
    #[derive(Clone, Debug)]
    pub struct Finder<'n> { needle: &'n [u8], state: [u64; STATE_WORDS] }

    impl<'n> Finder<'n> {
        pub fn new<B: ?Sized + AsRef<[u8]>>(needle: &'n B) -> Finder<'n> {
            let needle = needle.as_ref();
            let (p, e) = (needle.as_ptr(), unsafe { needle.as_ptr().add(needle.len()) });
            let mut state = [0u64; STATE_WORDS];
            unsafe { raw::nvol_memmem_init(p, e, state.as_mut_ptr() as *mut u8) };
            Finder { needle, state }
        }
        #[inline]
        pub fn needle(&self) -> &[u8] { self.needle }
        #[inline]
        pub fn find(&self, haystack: &[u8]) -> Option<usize> {
            unsafe {
                let (h, n) = (haystack.as_ptr(), self.needle.as_ptr());
                let p = raw::nvol_memmem_find_raw(self.state.as_ptr() as *const u8, n, n.add(self.needle.len()), h, h.add(haystack.len()));
                if p.is_null() { None } else { Some(p as usize - h as usize) }
            }
        }
        /// Non-overlapping matches, like memchr::memmem::FindIter.
        #[inline]
        pub fn find_iter<'a, 'h>(&'a self, haystack: &'h [u8]) -> FindIter<'a, 'h, 'n> { FindIter { finder: self, haystack, pos: 0 } }
    }

    #[derive(Clone, Debug)]
    pub struct FindIter<'a, 'h, 'n> { finder: &'a Finder<'n>, haystack: &'h [u8], pos: usize }
    impl<'a, 'h, 'n> Iterator for FindIter<'a, 'h, 'n> {
        type Item = usize;
        #[inline]
        fn next(&mut self) -> Option<usize> {
            let hay = self.haystack.get(self.pos..)?;
            let i = self.finder.find(hay)?;
            let at = self.pos + i;
            self.pos = at + core::cmp::max(1, self.finder.needle.len());
            Some(at)
        }
    }

    /// One-shot search (memchr::memmem::find): Rabin-Karp below 64 bytes, else a Finder.
    #[inline]
    pub fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
        if haystack.len() < 64 {
            unsafe {
                let (h, n) = (haystack.as_ptr(), needle.as_ptr());
                let p = raw::nvol_memmem_rk_oneshot(n, n.add(needle.len()), h, h.add(haystack.len()));
                return if p.is_null() { None } else { Some(p as usize - h as usize) };
            }
        }
        Finder::new(needle).find(haystack)
    }
    /// One-shot non-overlapping matches (collects; use Finder::find_iter to stream).
    pub fn find_iter(haystack: &[u8], needle: &[u8]) -> std::vec::Vec<usize> { Finder::new(needle).find_iter(haystack).collect() }
}

/// Packed multi-literal search (aho_corasick::packed equivalent, LeftmostFirst).
pub mod packed {
    use super::raw;

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct Match { pub pattern: usize, pub start: usize, pub end: usize }

    #[derive(Clone, Debug)]
    pub struct Searcher { blob: std::vec::Vec<u64>, state: std::boxed::Box<[u64; 306]> }

    impl Searcher {
        /// None when Teddy can't be used (same cases as aho-corasick's packed builder).
        pub fn new<I, P>(patterns: I) -> Option<Searcher> where I: IntoIterator<Item = P>, P: AsRef<[u8]> {
            let pats: std::vec::Vec<P> = patterns.into_iter().collect();
            let n = pats.len();
            let total = 8 + 16 * n + pats.iter().map(|p| p.as_ref().len()).sum::<usize>();
            let mut blob = std::vec![0u64; (total + 7) / 8];
            {
                let b = unsafe { core::slice::from_raw_parts_mut(blob.as_mut_ptr() as *mut u8, blob.len() * 8) };
                b[..8].copy_from_slice(&(n as u64).to_le_bytes());
                let mut pos = 8 + 16 * n;
                for (i, p) in pats.iter().enumerate() {
                    let p = p.as_ref();
                    b[8 + 16 * i..16 + 16 * i].copy_from_slice(&(pos as u64).to_le_bytes());
                    b[16 + 16 * i..24 + 16 * i].copy_from_slice(&(p.len() as u64).to_le_bytes());
                    b[pos..pos + p.len()].copy_from_slice(p);
                    pos += p.len();
                }
            }
            let mut state = std::boxed::Box::new([0u64; 306]);
            unsafe { raw::nvol_teddy_init(blob.as_ptr() as *const u8, state.as_mut_ptr() as *mut u8) };
            if state[0] == 0 { None } else { Some(Searcher { blob, state }) }
        }
        #[inline]
        pub fn find(&self, haystack: &[u8]) -> Option<Match> { self.find_in(haystack, 0..haystack.len()) }
        /// Like aho_corasick::packed::Searcher::find_in (the regex-automata prefilter entry point).
        #[inline]
        pub fn find_in(&self, haystack: &[u8], span: core::ops::Range<usize>) -> Option<Match> {
            assert!(span.start <= span.end && span.end <= haystack.len());
            unsafe {
                let h = haystack.as_ptr();
                let b = self.blob.as_ptr() as *const u8;
                let r = raw::nvol_teddy_find_raw(self.state.as_ptr() as *const u8, b, h.add(span.start), h.add(span.end));
                if r == usize::MAX { return None; }
                let pattern = r & 0xFF;
                let len = (b.add(16 + 16 * pattern) as *const u64).read_unaligned() as usize;
                let start = span.start + (r >> 8);
                Some(Match { pattern, start, end: start + len })
            }
        }
        /// Non-overlapping leftmost-first matches.
        pub fn find_iter<'s, 'h>(&'s self, haystack: &'h [u8]) -> FindIter<'s, 'h> { FindIter { s: self, haystack, pos: 0 } }
    }

    pub struct FindIter<'s, 'h> { s: &'s Searcher, haystack: &'h [u8], pos: usize }
    impl<'s, 'h> Iterator for FindIter<'s, 'h> {
        type Item = Match;
        #[inline]
        fn next(&mut self) -> Option<Match> {
            if self.pos > self.haystack.len() { return None; }
            let m = self.s.find_in(self.haystack, self.pos..self.haystack.len())?;
            self.pos = m.end;
            Some(m)
        }
    }
}

